import React, { useState, useEffect } from 'react';
import { BarChart, Bar, LineChart, Line, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { Wine, TrendingUp, Package, Globe, Leaf } from 'lucide-react';
import './App.css';

const API_BASE = 'http://localhost:8000/api';

export default function App() {
  const [activeTab, setActiveTab] = useState('Comercio');
  const [data, setData] = useState({
    Comercio: [],
    Producao: [],
    Exportacao: [],
    Importacao: [],
    Processamento: []
  });
  const [stats, setStats] = useState({
    comercioTotal: 0,
    producaoTotal: 0,
    exportacaoTotal: 0,
    comparativo: null
  });
  const [ano, setAno] = useState(2024);
  const [loading, setLoading] = useState(false);

  const tabs = [
    { id: 'Comercio', label: '🛍️ Comercialização' },
    { id: 'Producao', label: '🍇 Produção' },
    { id: 'Exportacao', label: '✈️ Exportação' },
    { id: 'Importacao', label: '📦 Importação' },
    { id: 'Processamento', label: '⚙️ Processamento' }
  ];

  useEffect(() => {
    fetchAllData();
  }, [ano]);

  const fetchAllPages = async (url) => {
    let allResults = [];
    let nextUrl = url;

    while (nextUrl) {
      try {
        const res = await fetch(nextUrl);
        const data = await res.json();
        allResults = [...allResults, ...(data.results || [])];
        nextUrl = data.next;
      } catch (err) {
        console.error('Erro ao buscar página:', err);
        break;
      }
    }

    return allResults;
  };

  const fetchAllData = async () => {
    setLoading(true);
    try {
      const [comData, prodData, expData, impData, procData, compData] = await Promise.all([
        fetchAllPages(`${API_BASE}/Comercio/?ano=${ano}`),
        fetchAllPages(`${API_BASE}/Producao/?ano=${ano}`),
        fetchAllPages(`${API_BASE}/Exportacao/?ano=${ano}`),
        fetchAllPages(`${API_BASE}/Importacao/?ano=${ano}`),
        fetchAllPages(`${API_BASE}/Processamento/?ano=${ano}`),
        fetch(`${API_BASE}/comparativo/${ano}/`).then(r => r.json())
      ]);

      setData({
        Comercio: comData || [],
        Producao: prodData || [],
        Exportacao: expData || [],
        Importacao: impData || [],
        Processamento: procData || []
      });

      setStats({
        comercioTotal: comData?.reduce((sum, item) => sum + (item.Quantidade_L || 0), 0) || 0,
        producaoTotal: prodData?.reduce((sum, item) => sum + (item.Quantidade_L || 0), 0) || 0,
        exportacaoTotal: expData?.reduce((sum, item) => sum + (item.Quantidade_Kg || 0), 0) || 0,
        comparativo: compData
      });
    } catch (err) {
      console.error('Erro ao buscar dados:', err);
    }
    setLoading(false);
  };

  const formatarNumero = (num) => {
    if (num >= 1000000) return (num / 1000000).toFixed(2) + 'M';
    if (num >= 1000) return (num / 1000).toFixed(2) + 'K';
    return num.toFixed(2);
  };

  const processarDadosPorCategoria = (items) => {
    const agrupado = items.reduce((acc, item) => {
      const categoria = item.Categoria || item.Tipo || 'Outro';
      const quantidade = item.Quantidade_L || item.Quantidade_Kg || 0;
      const existing = acc.find(a => a.nome === categoria);
      if (existing) {
        existing.valor += quantidade;
      } else {
        acc.push({ nome: categoria, valor: quantidade });
      }
      return acc;
    }, []);
    return agrupado.sort((a, b) => b.valor - a.valor).slice(0, 8);
  };

  const StatBox = ({ icon: Icon, label, valor }) => (
    <div className="stat-box">
      <div className="stat-box-content">
        <h3>{label}</h3>
        <div className="stat-box-value">{formatarNumero(valor)}</div>
      </div>
      <Icon className="stat-box-icon" size={48} />
    </div>
  );

  const dados = data[activeTab];
  const dadosGrafico = processarDadosPorCategoria(dados);

  return (
    <div className="App">
      <div className="max-w-7xl">
        {/* HEADER */}
        <div className="header-container">
          <h1>
            <Wine size={40} />
            Dashboard de Vinhos
          </h1>
          <p>Análise completa de produção, comercialização e exportação</p>
        </div>

        {/* FILTRO DE ANO */}
        <div className="filter-container">
          <input
            type="number"
            value={ano}
            onChange={(e) => setAno(parseInt(e.target.value))}
            placeholder="Ano"
            min="2000"
            max="2030"
          />
          {loading && <div className="loading-spinner">⏳ Carregando dados...</div>}
        </div>

        {/* STATS */}
        <div className="stats-grid">
          <StatBox icon={Wine} label="Comercialização" valor={stats.comercioTotal} />
          <StatBox icon={Package} label="Produção" valor={stats.producaoTotal} />
          <StatBox icon={Globe} label="Exportação" valor={stats.exportacaoTotal} />
          <StatBox
            icon={TrendingUp}
            label="% Exportado"
            valor={stats.comparativo?.percentual_exportado || 0}
          />
        </div>

        {/* TABS */}
        <div className="tabs-container">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              className={`tab-button ${activeTab === tab.id ? 'active' : ''}`}
              onClick={() => setActiveTab(tab.id)}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* GRÁFICOS */}
        <div className="charts-grid">
          {/* Gráfico 1: Por Categoria */}
          <div className="chart-container">
            <h3 className="chart-title">📊 Top Categorias</h3>
            {dadosGrafico.length > 0 ? (
              <ResponsiveContainer width="100%" height={350}>
                <BarChart data={dadosGrafico} margin={{ top: 20, right: 30, left: 0, bottom: 80 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
                  <XAxis 
                    dataKey="nome" 
                    angle={-45} 
                    textAnchor="end" 
                    height={100}
                    style={{ fontSize: '12px', fill: '#6b7280' }}
                  />
                  <YAxis style={{ fontSize: '12px', fill: '#6b7280' }} />
                  <Tooltip 
                    formatter={(value) => [formatarNumero(value), 'Quantidade']}
                    contentStyle={{ 
                      backgroundColor: '#fff', 
                      border: '2px solid #8b5cf6',
                      borderRadius: '8px',
                      boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
                    }}
                  />
                  <Bar 
                    dataKey="valor" 
                    fill="#8b5cf6" 
                    radius={[12, 12, 0, 0]}
                    animationDuration={800}
                  />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <p style={{ textAlign: 'center', color: '#6b7280', padding: '2rem' }}>Sem dados disponíveis</p>
            )}
          </div>

          {/* Gráfico 2: Distribuição */}
          <div className="chart-container">
            <h3 className="chart-title">🥧 Distribuição por Tipo</h3>
            {dadosGrafico.length > 0 ? (
              <ResponsiveContainer width="100%" height={350}>
                <PieChart>
                  <Pie
                    data={dadosGrafico.slice(0, 6)}
                    dataKey="valor"
                    nameKey="nome"
                    cx="50%"
                    cy="50%"
                    outerRadius={110}
                    innerRadius={60}
                    paddingAngle={2}
                    animationDuration={800}
                    label={({ nome, percent }) => `${nome} ${(percent * 100).toFixed(1)}%`}
                  >
                    {['#8b5cf6', '#22c55e', '#a78bfa', '#16a34a', '#c084fc', '#86efac'].map((cor, idx) => (
                      <Cell key={idx} fill={cor} />
                    ))}
                  </Pie>
                  <Tooltip 
                    formatter={(value) => [formatarNumero(value), 'Quantidade']}
                    contentStyle={{ 
                      backgroundColor: '#fff', 
                      border: '2px solid #22c55e',
                      borderRadius: '8px',
                      boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
                    }}
                  />
                </PieChart>
              </ResponsiveContainer>
            ) : (
              <p style={{ textAlign: 'center', color: '#6b7280', padding: '2rem' }}>Sem dados disponíveis</p>
            )}
          </div>
        </div>

        {/* TABELA */}
        <div className="table-container">
          <div className="table-header">
            <h3>
              {activeTab === 'Comercio' && '🛍️ Dados de Comercialização'}
              {activeTab === 'Producao' && '🍇 Dados de Produção'}
              {activeTab === 'Exportacao' && '✈️ Dados de Exportação'}
              {activeTab === 'Importacao' && '📦 Dados de Importação'}
              {activeTab === 'Processamento' && '⚙️ Dados de Processamento'}
            </h3>
          </div>
          <div className="table-wrapper">
            <table>
              <thead>
                <tr>
                  <th>Produto / Tipo</th>
                  <th>
                    {activeTab === 'Processamento' ? 'Cultivar' : activeTab === 'Exportacao' || activeTab === 'Importacao' ? 'País' : 'Categoria'}
                  </th>
                  <th style={{ textAlign: 'right' }}>Quantidade</th>
                </tr>
              </thead>
              <tbody>
                {dados.slice(0, 10).map((item, idx) => (
                  <tr key={idx}>
                    <td>{item.Produto || item.Tipo || '-'}</td>
                    <td>{item.Categoria || item.Países || item.Cultivar || '-'}</td>
                    <td style={{ textAlign: 'right' }}>
                      {formatarNumero(item.Quantidade_L || item.Quantidade_Kg || 0)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* FOOTER */}
        <div className="footer">
          <p>📅 Dados de {ano} • Atualizado em tempo real • Dashboard de Vinhos v1.0</p>
        </div>
      </div>
    </div>
  );
}
